using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.SqlClient;
using RepairCenter.Api.Data;
using RepairCenter.Api.Models;
using System.Data;
namespace RepairCenter.Api.Controllers;
[ApiController]
[Route("api/orders")]
public sealed class OrdersController : ControllerBase
{
 private readonly SqlConnectionFactory _factory; public OrdersController(SqlConnectionFactory factory)=>_factory=factory;
 private const string Q="SELECT ro.RepairOrderID,ro.OrderNumber,ro.EquipmentID,c.FullName,CONCAT(t.TypeName,N' ',b.BrandName,N' ',m.ModelName),e.SerialNumber,ro.AcceptedAt,ro.IssuedAt,ro.FaultDescription,ro.RepairCost,ro.OrderStatusID,s.StatusName,ISNULL(STUFF((SELECT N', '+emp.FullName FROM dbo.Course_project_0502_OrderAssignments oa JOIN dbo.Course_project_0502_Employees emp ON emp.EmployeeID=oa.EmployeeID WHERE oa.RepairOrderID=ro.RepairOrderID FOR XML PATH(''),TYPE).value('.','NVARCHAR(MAX)'),1,2,N''),N'') FROM dbo.Course_project_0502_RepairOrders ro JOIN dbo.Course_project_0502_Equipment e ON e.EquipmentID=ro.EquipmentID JOIN dbo.Course_project_0502_Clients c ON c.ClientID=e.ClientID JOIN dbo.Course_project_0502_EquipmentModels m ON m.EquipmentModelID=e.EquipmentModelID JOIN dbo.Course_project_0502_EquipmentBrands b ON b.EquipmentBrandID=m.EquipmentBrandID JOIN dbo.Course_project_0502_EquipmentTypes t ON t.EquipmentTypeID=m.EquipmentTypeID JOIN dbo.Course_project_0502_OrderStatuses s ON s.OrderStatusID=ro.OrderStatusID";
 private static object Map(SqlDataReader r)=>new{RepairOrderID=r.GetInt32(0),OrderNumber=r.GetString(1),EquipmentID=r.GetInt32(2),ClientName=r.GetString(3),Equipment=r.GetString(4),SerialNumber=r.GetString(5),AcceptedAt=r.GetDateTime(6),IssuedAt=r.IsDBNull(7)?(DateTime?)null:r.GetDateTime(7),FaultDescription=r.GetString(8),RepairCost=r.GetDecimal(9),OrderStatusID=r.GetInt32(10),OrderStatus=r.GetString(11),AssignedEmployees=r.IsDBNull(12)?string.Empty:r.GetString(12)};
 [HttpGet] public async Task<IActionResult> GetAll([FromQuery]string? search,[FromQuery]DateTime? date,[FromQuery]DateTime? fromDate,[FromQuery]DateTime? toDate){if(fromDate.HasValue&&toDate.HasValue&&toDate.Value.Date<fromDate.Value.Date)return BadRequest(new{message="Дата окончания раньше даты начала."});await using var c=_factory.Create();await c.OpenAsync();await using var cmd=c.CreateCommand();cmd.CommandText=Q+" WHERE ro.IsCancelled=0 AND (@s IS NULL OR ro.OrderNumber LIKE @p OR c.FullName LIKE @p OR ro.FaultDescription LIKE @p) AND (@d IS NULL OR CAST(ro.AcceptedAt AS date)=@d) AND (@f IS NULL OR ro.AcceptedAt>=@f) AND (@t IS NULL OR ro.AcceptedAt<DATEADD(day,1,@t)) ORDER BY ro.AcceptedAt DESC";cmd.Parameters.Add("@s",SqlDbType.NVarChar,150).Value=string.IsNullOrWhiteSpace(search)?DBNull.Value:search.Trim();cmd.Parameters.Add("@p",SqlDbType.NVarChar,350).Value=string.IsNullOrWhiteSpace(search)?DBNull.Value:"%"+search.Trim()+"%";cmd.Parameters.Add("@d",SqlDbType.Date).Value=date.HasValue?date.Value.Date:DBNull.Value;cmd.Parameters.Add("@f",SqlDbType.Date).Value=fromDate.HasValue?fromDate.Value.Date:DBNull.Value;cmd.Parameters.Add("@t",SqlDbType.Date).Value=toDate.HasValue?toDate.Value.Date:DBNull.Value;var rows=new List<object>();await using var r=await cmd.ExecuteReaderAsync();while(await r.ReadAsync())rows.Add(Map(r));return Ok(rows);}
 [HttpGet("{id:int}")] public async Task<IActionResult> Get(int id){await using var c=_factory.Create();await c.OpenAsync();await using var cmd=c.CreateCommand();cmd.CommandText=Q+" WHERE ro.RepairOrderID=@id AND ro.IsCancelled=0";cmd.Parameters.Add("@id",SqlDbType.Int).Value=id;await using var r=await cmd.ExecuteReaderAsync();return await r.ReadAsync()?Ok(Map(r)):NotFound();}
 [HttpGet("{id:int}/status")] public async Task<IActionResult> GetStatus(int id){await using var c=_factory.Create();await c.OpenAsync();await using var cmd=c.CreateCommand();cmd.CommandText="SELECT ro.RepairOrderID,ro.OrderNumber,s.StatusName,ro.AcceptedAt,ro.IssuedAt FROM dbo.Course_project_0502_RepairOrders ro JOIN dbo.Course_project_0502_OrderStatuses s ON s.OrderStatusID=ro.OrderStatusID WHERE ro.RepairOrderID=@id";cmd.Parameters.Add("@id",SqlDbType.Int).Value=id;await using var r=await cmd.ExecuteReaderAsync();if(!await r.ReadAsync())return NotFound();return Ok(new{RepairOrderID=r.GetInt32(0),OrderNumber=r.GetString(1),Status=r.GetString(2),AcceptedAt=r.GetDateTime(3),IssuedAt=r.IsDBNull(4)?(DateTime?)null:r.GetDateTime(4)});}
 [HttpGet("{id:int}/history")] public async Task<IActionResult> GetHistory(int id){var rows=new List<object>();await using var c=_factory.Create();await c.OpenAsync();await using var cmd=c.CreateCommand();cmd.CommandText="SELECT h.StatusHistoryID,h.RepairOrderID,s.StatusName,h.ChangedAt,h.ChangeNote FROM dbo.Course_project_0502_RepairOrderStatusHistory h JOIN dbo.Course_project_0502_OrderStatuses s ON s.OrderStatusID=h.OrderStatusID WHERE h.RepairOrderID=@id ORDER BY h.ChangedAt,h.StatusHistoryID";cmd.Parameters.Add("@id",SqlDbType.Int).Value=id;await using var r=await cmd.ExecuteReaderAsync();while(await r.ReadAsync())rows.Add(new{StatusHistoryID=r.GetInt32(0),RepairOrderID=r.GetInt32(1),Status=r.GetString(2),ChangedAt=r.GetDateTime(3),ChangeNote=r.IsDBNull(4)?null:r.GetString(4)});return Ok(rows);}
 [HttpPost] public async Task<IActionResult> Create(CreateOrderRequest request){if(request.IssuedAt.HasValue&&request.IssuedAt.Value.Date<request.AcceptedAt.Date)return BadRequest(new{message="Дата выдачи раньше даты приёма."});await using var c=_factory.Create();await c.OpenAsync();await using(var statusCheck=c.CreateCommand()){statusCheck.CommandText="SELECT IsFinal FROM dbo.Course_project_0502_OrderStatuses WHERE OrderStatusID=@id";statusCheck.Parameters.Add("@id",SqlDbType.Int).Value=request.OrderStatusID;var finalValue=await statusCheck.ExecuteScalarAsync();if(finalValue==null||finalValue==DBNull.Value)return BadRequest(new{message="Указанный статус не найден."});if(Convert.ToBoolean(finalValue)&&!request.IssuedAt.HasValue)return BadRequest(new{message="Для финального статуса необходимо указать IssuedAt."});}await using var tx=(SqlTransaction)await c.BeginTransactionAsync();try{string number="RC-"+DateTime.Now.ToString("yyMMddHHmmssfff");int id;await using(var cmd=c.CreateCommand()){cmd.Transaction=tx;cmd.CommandText="INSERT INTO dbo.Course_project_0502_RepairOrders(OrderNumber,EquipmentID,AcceptedAt,IssuedAt,FaultDescription,RepairCost,OrderStatusID,IsCancelled,CreatedAt) OUTPUT INSERTED.RepairOrderID VALUES(@n,@e,@a,@i,@f,@c,@s,0,SYSDATETIME())";cmd.Parameters.Add("@n",SqlDbType.NVarChar,20).Value=number;cmd.Parameters.Add("@e",SqlDbType.Int).Value=request.EquipmentID;cmd.Parameters.Add("@a",SqlDbType.Date).Value=request.AcceptedAt.Date;cmd.Parameters.Add("@i",SqlDbType.Date).Value=request.IssuedAt.HasValue?(object)request.IssuedAt.Value.Date:DBNull.Value;cmd.Parameters.Add("@f",SqlDbType.NVarChar,1000).Value=request.FaultDescription.Trim();var cp=cmd.Parameters.Add("@c",SqlDbType.Decimal);cp.Precision=10;cp.Scale=2;cp.Value=request.RepairCost;cmd.Parameters.Add("@s",SqlDbType.Int).Value=request.OrderStatusID;id=Convert.ToInt32(await cmd.ExecuteScalarAsync());}await AddHistory(c,tx,id,request.OrderStatusID,"Заказ создан через API");if(request.EmployeeID.GetValueOrDefault()>0)await AddAssignment(c,tx,id,request.EmployeeID.Value);await tx.CommitAsync();return CreatedAtAction(nameof(Get),new{id},new{RepairOrderID=id,OrderNumber=number});}catch{await tx.RollbackAsync();throw;}}
 [HttpPut("{id:int}")] public async Task<IActionResult> Update(int id,UpdateOrderRequest request){DateTime accepted;int oldStatus;await using(var c0=_factory.Create()){await c0.OpenAsync();await using var q=c0.CreateCommand();q.CommandText="SELECT AcceptedAt,OrderStatusID FROM dbo.Course_project_0502_RepairOrders WHERE RepairOrderID=@id AND IsCancelled=0";q.Parameters.Add("@id",SqlDbType.Int).Value=id;await using var r=await q.ExecuteReaderAsync();if(!await r.ReadAsync())return NotFound();accepted=r.GetDateTime(0);oldStatus=r.GetInt32(1);}if(request.IssuedAt.HasValue&&request.IssuedAt.Value.Date<accepted.Date)return BadRequest(new{message="Дата выдачи раньше даты приёма."});await using var c=_factory.Create();await c.OpenAsync();await using var tx=(SqlTransaction)await c.BeginTransactionAsync();try{await using(var cmd=c.CreateCommand()){cmd.Transaction=tx;cmd.CommandText="UPDATE dbo.Course_project_0502_RepairOrders SET FaultDescription=@f,RepairCost=@c,OrderStatusID=@s,IssuedAt=@i WHERE RepairOrderID=@id AND IsCancelled=0";cmd.Parameters.Add("@id",SqlDbType.Int).Value=id;cmd.Parameters.Add("@f",SqlDbType.NVarChar,1000).Value=request.FaultDescription.Trim();var cp=cmd.Parameters.Add("@c",SqlDbType.Decimal);cp.Precision=10;cp.Scale=2;cp.Value=request.RepairCost;cmd.Parameters.Add("@s",SqlDbType.Int).Value=request.OrderStatusID;cmd.Parameters.Add("@i",SqlDbType.Date).Value=request.IssuedAt.HasValue?(object)request.IssuedAt.Value.Date:DBNull.Value;if(await cmd.ExecuteNonQueryAsync()==0){await tx.RollbackAsync();return NotFound();}}if(oldStatus!=request.OrderStatusID)await AddHistory(c,tx,id,request.OrderStatusID,string.IsNullOrWhiteSpace(request.ChangeNote)?"Статус изменён через API":request.ChangeNote.Trim());if(request.EmployeeID.HasValue){await using(var cmd=c.CreateCommand()){cmd.Transaction=tx;cmd.CommandText="DELETE FROM dbo.Course_project_0502_OrderAssignments WHERE RepairOrderID=@id";cmd.Parameters.Add("@id",SqlDbType.Int).Value=id;await cmd.ExecuteNonQueryAsync();}if(request.EmployeeID.Value>0)await AddAssignment(c,tx,id,request.EmployeeID.Value);}await tx.CommitAsync();return NoContent();}catch{await tx.RollbackAsync();throw;}}
 [HttpDelete("{id:int}")] public async Task<IActionResult> Cancel(int id,[FromQuery]string? reason){await using var c=_factory.Create();await c.OpenAsync();await using var tx=(SqlTransaction)await c.BeginTransactionAsync();try{int status;await using(var q=c.CreateCommand()){q.Transaction=tx;q.CommandText="SELECT OrderStatusID FROM dbo.Course_project_0502_RepairOrders WHERE RepairOrderID=@id AND IsCancelled=0";q.Parameters.Add("@id",SqlDbType.Int).Value=id;var v=await q.ExecuteScalarAsync();if(v==null||v==DBNull.Value){await tx.RollbackAsync();return NotFound();}status=Convert.ToInt32(v);}var why=string.IsNullOrWhiteSpace(reason)?"Отменён администратором API":reason.Trim();if(why.Length>250)why=why.Substring(0,250);await using(var cmd=c.CreateCommand()){cmd.Transaction=tx;cmd.CommandText="UPDATE dbo.Course_project_0502_RepairOrders SET IsCancelled=1,CancellationNote=@n WHERE RepairOrderID=@id";cmd.Parameters.Add("@id",SqlDbType.Int).Value=id;cmd.Parameters.Add("@n",SqlDbType.NVarChar,250).Value=why;await cmd.ExecuteNonQueryAsync();}await AddHistory(c,tx,id,status,"Заказ отменён: "+why);await tx.CommitAsync();return NoContent();}catch{await tx.RollbackAsync();throw;}}
 private static async Task AddHistory(SqlConnection c,SqlTransaction tx,int orderId,int status,string note){if(note.Length>250)note=note.Substring(0,250);await using var cmd=c.CreateCommand();cmd.Transaction=tx;cmd.CommandText="INSERT INTO dbo.Course_project_0502_RepairOrderStatusHistory(RepairOrderID,OrderStatusID,ChangedAt,ChangedByUserID,ChangeNote) VALUES(@o,@s,SYSDATETIME(),NULL,@n)";cmd.Parameters.Add("@o",SqlDbType.Int).Value=orderId;cmd.Parameters.Add("@s",SqlDbType.Int).Value=status;cmd.Parameters.Add("@n",SqlDbType.NVarChar,250).Value=note;await cmd.ExecuteNonQueryAsync();}
 private static async Task AddAssignment(SqlConnection c,SqlTransaction tx,int orderId,int employeeId){await using var cmd=c.CreateCommand();cmd.Transaction=tx;cmd.CommandText="INSERT INTO dbo.Course_project_0502_OrderAssignments(RepairOrderID,EmployeeID,AssignedAt,AssignmentNote) VALUES(@o,@e,SYSDATETIME(),N'Ответственный исполнитель')";cmd.Parameters.Add("@o",SqlDbType.Int).Value=orderId;cmd.Parameters.Add("@e",SqlDbType.Int).Value=employeeId;await cmd.ExecuteNonQueryAsync();}
}
